;$('exportBtn').addEventListener('click',function(){toast('导出请求已提交')});document.querySelectorAll('[data-clear]').forEach(function(b){b.addEventListener('click',function(){var i=$(b.dataset.clear);i.value='';b.style.display='none';i.focus()})});document.querySelectorAll('input').forEach(function(i){i.addEventListener('input',function(){var b=document.querySelector('[data-clear=\"'+i.id+'\"]');if(b)b.style.display=i.value?'block':'none'})});$('tableBody').addEventListener('click',function(e){var a=e.target.closest('[data-action]');if(a){if(a.dataset.action==='source')openSource();else if(a.dataset.action==='disable')openConfirm('disable',a.dataset.id);else if(a.dataset.action==='pay')openConfirm('pay',a.dataset.id);else toast('已设置为测试用户');return}var c=e.target.closest('[data-select]');if(c){if(c.checked)state.selected[c.dataset.select]=true;else delete state.selected[c.dataset.select];updateSel()}});$('pgNav').addEventListener('click',function(e){var b=e.target.closest('[data-page]');if(!b||b.disabled)return;state.page=Number(b.dataset.page);state.selected={};render()});$('pageSize').addEventListener('change',function(){state.pageSize=Number($('pageSize').value);state.page=1;state.selected={};render()});$('jumpPage').addEventListener('keydown',function(e){if(e.key!=='Enter')return;state.page=Math.max(1,Number($('jumpPage').value)||1);$('jumpPage').value='1';state.selected={};render()});document.querySelectorAll('[data-batch]').forEach(function(b){b.addEventListener('click',function(){if(b.dataset.batch==='source')openSource();else if(b.dataset.batch==='disable')openConfirm('disable',users[5].id);else toast(b.textContent.trim()+'已执行')})});$('sourceClose').onclick=closeSource;$('sourceCancel').onclick=closeSource;$('sourceConfirm').onclick=function(){if(!$('sourceInput').value.trim()){$('sourceError').textContent='请输入来源唯一标识码或 linkuuid';return}closeSource();toast('用户来源已更新')};$('dialogClose').onclick=closeConfirm;$('dialogCancel').onclick=closeConfirm;$('dialogConfirm').on